package local.purelightclient;
import java.util.*;import java.nio.file.*;import java.util.concurrent.atomic.AtomicReference;import net.minecraft.client.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.resources.Identifier;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.level.GameType;import net.minecraft.world.item.*;import net.minecraft.world.effect.MobEffectInstance;import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.client.event.ClientTickEvent;import net.spell_engine.internals.*;import net.spell_engine.client.render.tint.*;
@Mod(value="spatial_client_probe",dist=Dist.CLIENT) public class PurelightClientProbe {
 int ticks,phase,at;volatile boolean pending;List<String> lines=new ArrayList<>();AtomicReference<Throwable> error=new AtomicReference<>();int body,armor;
 public PurelightClientProbe(){NeoForge.EVENT_BUS.addListener(this::tick);}
 void check(boolean b,String s){lines.add((b?"PASS ":"FAIL ")+s);if(!b)throw new AssertionError(s);}
 void server(java.util.function.Consumer<ServerPlayer> job){var mc=Minecraft.getInstance();pending=true;mc.getSingleplayerServer().execute(()->{try{job.accept(mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID()));}catch(Throwable e){error.set(e);}finally{pending=false;}});}
 void next(){phase++;at=ticks;}
 void finish(){phase=99;var mc=Minecraft.getInstance();try{Files.write(mc.gameDirectory.toPath().resolve("spatial-client-checks.txt"),lines);Files.writeString(mc.gameDirectory.toPath().resolve("spatial-client-result.txt"),lines.stream().anyMatch(x->x.startsWith("FAIL"))?"FAIL":"PASS");}catch(Exception ignored){}mc.stop();}
 void tick(ClientTickEvent.Post event){var mc=Minecraft.getInstance();ticks++;org.lwjgl.glfw.GLFW.glfwHideWindow(mc.getWindow().handle());if(phase==99)return;try{
  if(error.get()!=null)throw new RuntimeException(error.get());if(pending||mc.player==null||mc.level==null||mc.getSingleplayerServer()==null)return;if(ticks-at>1000)throw new AssertionError("Timeout");
  if(phase==0){mc.options.pauseOnLostFocus=false;mc.setScreenAndShow(null);mc.options.setCameraType(CameraType.THIRD_PERSON_FRONT);if(!mc.gui.hud.isHidden())mc.gui.hud.toggle();server(p->{p.setGameMode(GameType.SURVIVAL);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);p.setHealth(100);p.teleportTo(0,101,0);p.setNoGravity(true);p.setYRot(0);p.setXRot(0);p.removeAllEffects();for(var e:p.level().getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(100)))if(e!=p)e.discard();p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.DIAMOND_HELMET));p.setItemSlot(EquipmentSlot.CHEST,new ItemStack(Items.DIAMOND_CHESTPLATE));p.setItemSlot(EquipmentSlot.LEGS,new ItemStack(Items.DIAMOND_LEGGINGS));p.setItemSlot(EquipmentSlot.FEET,new ItemStack(Items.DIAMOND_BOOTS));p.getPersistentData().putBoolean("final_purelight_active",true);p.getPersistentData().putLong("final_purelight_next",p.level().getGameTime()+10);FinalRules.status(p,"purelight_cost",-1,0,p);p.inventoryMenu.broadcastFullState();p.level().clockManager().setTotalTicks(p.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.WORLD_CLOCK).getOrThrow(net.minecraft.world.clock.WorldClocks.OVERWORLD),18000);});next();return;}
  if(ticks-at<35)return;
  if(phase==1){check(mc.player.hasEffect(FinalRules.effect("purelight_cost")),"Active Purelight synchronized");check(PurelightVisual.bodySubmissions>0,"Actual body submits full-bright gold passes");check(PurelightVisual.armorSubmissions>0,"Actual equipped armor submits gold passes");Screenshot.grab(mc,false);next();return;}
  if(phase==2){server(p->FinalPurelight.stop(p));next();return;}
  if(phase==3){check(!mc.player.hasEffect(FinalRules.effect("purelight_cost")),"Ending state clears client glow driver");body=PurelightVisual.bodySubmissions;armor=PurelightVisual.armorSubmissions;next();return;}
  if(phase==4){check(body==PurelightVisual.bodySubmissions&&armor==PurelightVisual.armorSubmissions,"Body and armor stop glowing without stale render state");Screenshot.grab(mc,false);finish();}
 }catch(Throwable e){e.printStackTrace();lines.add("FAIL "+e);finish();}}
}
